/// <summary>
/// Purpose of class is to provide a list of EDT's and their equivalent Tables used for lookups, when a simple generic search is enough, but the standard doesn't provide this relation
/// </summary>
class TFMSearchEDTsToLookupTable
{
}

Method.Source:
	public static Map EDTs2Tables()
    {
        Map EDTs2Tables = new Map(Types::String, Types::String);
        TFMSearchEDTsToTablesRelation   custEdtRels;
        EDTs2Tables.insert(extendedTypeStr(WHSLicensePlateId), tableStr(WHSLicensePlate));

        while select custEdtRels
        {
            EDTs2Tables.insert(custEdtRels.EDTBasedOn, custEdtRels.TableName);
        }

        //TODO: Make Form in client where new lookup relations can be added to this list.

        return EDTs2Tables;
    }
